import subprocess

def execute_ls_command(dir_path: str) -> str:
    try:
        result = subprocess.run(['ls', '-l', dir_path], capture_output=True, text=True)
        return result.stdout
    except Exception as e:
        print(f"Error: {e}")
        return ''

# Example usage
print(execute_ls_command('/some/directory'))

import subprocess

try:
    result = subprocess.run(['ls', '-l', '/nonexistent'], capture_output=True, text=True)
    print(result.stdout)
except (subprocess.CalledProcessError, FileNotFoundError, PermissionError) as e:
    print(f"Error: {e}")
